--
-- Table structure for table `blade_dept`
--

DROP TABLE IF EXISTS `blade_dept`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_dept` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '000000' COMMENT '租户ID',
  `parent_id` bigint DEFAULT '0' COMMENT '父主键',
  `dept_type` tinyint NOT NULL DEFAULT '2' COMMENT '节点类型:1分部 2部门(对齐ecology hrmsubcompany/hrmdepartment双表模型)',
  `ancestors` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '祖级列表',
  `dept_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门名',
  `dept_code` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '编号(对齐subcompanycode/departmentcode),租户内唯一',
  `subcompany_id` bigint DEFAULT NULL COMMENT '所属分部节点id(对齐hrmdepartment.subcompanyid1冗余外键),仅部门节点填写',
  `full_name` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门全称',
  `sort` int DEFAULT NULL COMMENT '排序',
  `canceled` tinyint NOT NULL DEFAULT '0' COMMENT '封存标志:0正常 1封存(可解封,语义≠is_deleted)',
  `manager_user_id` bigint DEFAULT NULL COMMENT '部门主管/协管人用户id(对齐coadjutant)',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `is_deleted` int DEFAULT '0' COMMENT '是否已删除',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `code` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '部门编码',
  `status` int DEFAULT NULL COMMENT '业务状态[1:正常]',
  `out_key` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '外部系统同步外键(对齐outkey)',
  `sync_uuid` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '同步UUID(对齐uuid)',
  `pinyin` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '拼音搜索列(由dept_name+full_name生成)',
  `limit_users` int DEFAULT NULL COMMENT '分部人员数上限(对齐limitUsers,仅超管可设)',
  `dept_level` int DEFAULT NULL COMMENT '层级号(由ancestors推导,10级上限)',
  `ecology_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_blade_dept_tenant_code` (`tenant_id`,`dept_code`),
  KEY `idx_blade_dept_subcompany` (`subcompany_id`),
  KEY `idx_blade_dept_type` (`tenant_id`,`dept_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='部门表';
/*!40101 SET character_set_client = @saved_cs_client */;

