DROP TABLE IF EXISTS `blade_message_attachment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_message_attachment` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) DEFAULT NULL COMMENT '租户ID',
  `message_id` bigint NOT NULL COMMENT '消息ID',
  `file_id` varchar(64) DEFAULT NULL COMMENT 'blade-resource 文件ID',
  `file_name` varchar(200) DEFAULT NULL COMMENT '文件名',
  `file_url` varchar(500) DEFAULT NULL COMMENT '文件访问地址',
  `file_size` bigint DEFAULT NULL COMMENT '文件大小（字节）',
  `file_type` varchar(50) DEFAULT NULL COMMENT '文件类型',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `update_user` bigint DEFAULT NULL COMMENT '更新人',
  `status` int DEFAULT NULL COMMENT '状态',
  `is_deleted` int DEFAULT NULL COMMENT '是否已删除',
  `create_dept` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_blade_message_attachment_message` (`message_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='消息附件';
