/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `blade_message_session` (
  `id` bigint NOT NULL COMMENT '主键',
  `tenant_id` varchar(50) NOT NULL COMMENT '租户ID',
