  PRIMARY KEY (`id`),
  KEY `idx_custom_op_action_op` (`op_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='自定义操作动作明细';
