--
-- Table structure for table `wf_node_timeout`
--

DROP TABLE IF EXISTS `wf_node_timeout`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_node_timeout` (
  `id` bigint NOT NULL COMMENT '主键（雪花 ID）',
  `tenant_id` varchar(12) NOT NULL DEFAULT '000000' COMMENT '租户',
  `def_id` bigint NOT NULL COMMENT '流程定义 ID',
  `node_key` varchar(64) NOT NULL COMMENT '节点 Key',
  `seq` int NOT NULL DEFAULT '0' COMMENT '排序（升序执行）',
  `enabled` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用 1=是 0=否',
  `start_type` tinyint NOT NULL DEFAULT '1' COMMENT '起算方式 1=节点到达(收到待办) 2=表单时间字段',
  `start_field` varchar(64) DEFAULT NULL COMMENT '起算=表单时间字段时的字段名',
  `duration_min` int DEFAULT NULL COMMENT '截止=相对时长时的分钟数',
  `end_type` tinyint NOT NULL DEFAULT '1' COMMENT '截止方式 1=相对(起算+时长) 2=固定时刻(HH:mm) 3=表单时间字段',
  `end_fixed_time` varchar(8) DEFAULT NULL COMMENT '截止=固定时刻时的 HH:mm',
  `end_field` varchar(64) DEFAULT NULL COMMENT '截止=表单时间字段时的字段名',
  `action_way` varchar(16) NOT NULL DEFAULT 'autoApprove' COMMENT '超时动作 autoApprove/forward/assign/remind',
  `target_node_key` varchar(64) DEFAULT NULL COMMENT '动作=forward 时的目标节点（扩展位，当前按 autoApprove 语义流转）',
  `operator_ids` varchar(255) DEFAULT NULL COMMENT '动作=assign 时的指定操作者（人力资源 ID 逗号分隔）',
  `opinion` varchar(255) DEFAULT NULL COMMENT '动作意见',
  `remind_types` varchar(32) DEFAULT NULL COMMENT '提醒方式 sys=流程提醒 ml=短信 sm=邮件（逗号分隔）',
  `remind_before_operator` tinyint NOT NULL DEFAULT '0' COMMENT '提醒对象：节点当前处理人 1=是 0=否',
  `remind_persons` varchar(255) DEFAULT NULL COMMENT '提醒对象：指定人员（人力资源 ID 逗号分隔）',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态:1正常 0禁用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_node_timeout_def_node` (`def_id`,`node_key`,`seq`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='节点超时规则（多条，对齐泛微超时设置）';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wf_node_timeout`
--

LOCK TABLES `wf_node_timeout` WRITE;
/*!40000 ALTER TABLE `wf_node_timeout` DISABLE KEYS */;
/*!40000 ALTER TABLE `wf_node_timeout` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `wf_process_definition`
--

DROP TABLE IF EXISTS `wf_process_definition`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_process_definition` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `proc_key` varchar(64) NOT NULL COMMENT '引擎流程Key（= BPMN process id）',
  `form_id` bigint DEFAULT NULL COMMENT '关联 workflow_bill.id（表单），可空',
  `name` varchar(200) NOT NULL COMMENT '流程名称',
  `bpmn_xml` mediumtext COMMENT 'BPMN 2.0 流程定义 XML（bpmn-js 画布产出，部署时下发引擎）',
  `version` int NOT NULL DEFAULT '1' COMMENT '版本号',
  `active_version_id` bigint unsigned DEFAULT NULL COMMENT '版本组锚点：指向当前激活版本的 defId；首版=自身id，NULL=单版本流程（组=自身）',
  `deployment_id` varchar(64) DEFAULT NULL COMMENT '最近一次正式部署的引擎部署ID（ACT_RE_DEPLOYMENT.ID_）；NULL=尚未正式部署/未落库',
  `is_free` tinyint NOT NULL DEFAULT '0' COMMENT '是否自由流程',
  `free_wf_type` tinyint DEFAULT NULL COMMENT '自由流程类型：1简易 2高级',
  `type` varchar(64) DEFAULT NULL COMMENT '路径类型（对齐 ecology path_type 字典 code）',
  `form_type` tinyint DEFAULT NULL COMMENT '对应表单类型：0自定义表单 1系统表单',
  `description` varchar(500) DEFAULT NULL COMMENT '路径描述',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '显示顺序',
  `tenant_id` varchar(32) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '0' COMMENT '0草稿 1已发布 2停用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除:1已删 0未删',
  `proc_def_id` varchar(64) DEFAULT NULL COMMENT '激活版本对应的 Flowable processDefinitionId（ACT_RE_PROCDEF.ID_）',
  `draft_revision` bigint NOT NULL DEFAULT '0' COMMENT '草稿修订号（D15/R11）：saveBpmn 原子递增；客户端保存携带 baseRevision 做乐观并发校验',
  `test_proc_def_id` varchar(64) DEFAULT NULL COMMENT '测试态最近一次测试部署的 processDefinitionId（procKey__test）；配置面板在 status=3 时优先读它；NULL=从未测试部署',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_proc_key_version` (`proc_key`,`version`,`is_deleted`),
  KEY `idx_form_status` (`form_id`,`status`),
  KEY `idx_active_version` (`active_version_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2105719187119816707 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程定义';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wf_process_definition`
--

LOCK TABLES `wf_process_definition` WRITE;
/*!40000 ALTER TABLE `wf_process_definition` DISABLE KEYS */;
