--
-- Table structure for table `wf_test_log`
--

DROP TABLE IF EXISTS `wf_test_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_test_log` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `def_id` bigint unsigned NOT NULL COMMENT '流程定义ID',
  `def_version` int DEFAULT NULL COMMENT '测试时的流程版本',
  `proc_key` varchar(100) DEFAULT NULL COMMENT '引擎流程Key（冗余，便于检索）',
  `def_name` varchar(200) DEFAULT NULL COMMENT '流程名称（冗余）',
  `test_user_id` bigint NOT NULL COMMENT '测试发起人用户ID',
  `test_user_name` varchar(100) DEFAULT NULL COMMENT '测试发起人姓名（冗余）',
  `test_time` datetime NOT NULL COMMENT '测试时间',
  `cost_ms` bigint NOT NULL DEFAULT '0' COMMENT '耗时（毫秒）',
  `test_status` int NOT NULL DEFAULT '0' COMMENT '测试结论 0未通过 1通过 2异常中断',
  `node_total` int NOT NULL DEFAULT '0' COMMENT '参与校验节点数',
  `node_passed` int NOT NULL DEFAULT '0' COMMENT '走通节点数',
  `reached_end` int NOT NULL DEFAULT '0' COMMENT '是否走到归档节点 1是 0否',
  `summary` varchar(1000) DEFAULT NULL COMMENT '结论摘要',
  `log_content` longtext COMMENT '测试日志正文（逐行文本）',
  `result_json` json DEFAULT NULL COMMENT '结构化结果：节点经过次数/路径/操作者',
  `inst_id` bigint DEFAULT NULL COMMENT '测试态实例ID（交互式测试；一次性测试为 NULL）',
  `tenant_id` varchar(32) NOT NULL DEFAULT '000000' COMMENT '租户ID',
  `create_user` bigint DEFAULT NULL COMMENT '创建人',
  `create_dept` bigint DEFAULT NULL COMMENT '创建部门',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` bigint DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态:1正常 0禁用',
  `is_deleted` int NOT NULL DEFAULT '0' COMMENT '逻辑删除',
  PRIMARY KEY (`id`),
  KEY `idx_def_time` (`def_id`,`test_time`),
  KEY `idx_user_time` (`test_user_id`,`test_time`)
) ENGINE=InnoDB AUTO_INCREMENT=2106532722903207938 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='流程测试日志';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `wf_test_log`
--

LOCK TABLES `wf_test_log` WRITE;
/*!40000 ALTER TABLE `wf_test_log` DISABLE KEYS */;
